-- Mega artwork provider for Gen1Recomp: indexed by a TEMPORARY Mega form key,
-- never by a saved species slot. Does not install battle, Pokedex or party hooks.
--
-- The source atlas is generated by tools/build_mega_atlas.py and is independent
-- of g9-battle-sprites-gen3's owned Pokemon.frontPic/backPic/icon wrappers.
local Atlas = {}
local PIC_BOX = 64
local KINDS = {
  front = true, back = true, icon = true,
  front_shiny = true, back_shiny = true, icon_shiny = true,
}

-- Pure frame math: checks every offset before any texture is loaded.
function Atlas.locate(index, slug, kind, frame)
  if type(slug) ~= "string" or not KINDS[kind] then return nil end
  local forms = type(index) == "table" and index.forms
  local form = type(forms) == "table" and forms[slug]
  local cell = form and form.variants and form.variants[kind]
  local count = cell and tonumber(cell.frames)
  if not count or count < 1 then return nil end
  local n = math.floor(tonumber(frame) or 0) % count
  for _, seg in ipairs(cell.segments or {}) do
    local first, nseg, cols, fs = tonumber(seg.first), tonumber(seg.frames),
      tonumber(seg.cols), tonumber(seg.fs)
    if first and nseg and cols and cols > 0 and fs and fs > 0
        and n >= first and n < first + nseg then
      local localFrame = n - first
      local fw, fh = tonumber(seg.fw) or fs, tonumber(seg.fh) or fs
      local cx, cy = tonumber(seg.cx) or 0, tonumber(seg.cy) or 0
      -- Segments in older committed atlases have no crop metadata.
      -- A normalized segment stores its common source-frame crop origin
      -- and actual packed rectangle, so hovering/bouncing never shifts.
      if fw < 1 or fh < 1 or cx < 0 or cy < 0
          or fw + cx > fs or fh + cy > fs then return nil end
      return {
        file = string.format("battle_%s_%d.png", kind, seg.sheet),
        x = seg.ox + (localFrame % cols) * fw,
        y = seg.oy + math.floor(localFrame / cols) * fh,
        fs = fs, fw = fw, fh = fh, cx = cx, cy = cy,
        frame = n, frames = count,
        fps = tonumber(cell.fps) or 8, slug = slug, kind = kind,
      }
    end
  end
  return nil
end

-- A small bounded page cache matters: 156 full-resolution pages would consume
-- gigabytes if all loaded as GPU textures at once. Frames are separately cached.
function Atlas.new(mod, index, graphics, timer, presentation)
  if type(index) ~= "table" or index.schema ~= 1 or type(index.forms) ~= "table" then
    return nil, "unsupported or missing Mega atlas index"
  end
  local G = graphics
  local self = { index = index }
  local pageCache, pageOrder = {}, {}
  local frameCache, frameOrder = {}, {}
  local logged = {}
  local pivots = setmetatable({}, { __mode = "k" })
  local inBattleDraw = false
  local unpackArgs = table.unpack or unpack

  -- The game's G9/HD draw wrappers are shared by EVERY sprite. Our previous
  -- version permanently inserted a second global draw shim; this could upset
  -- unrelated opponent rendering. Install a scoped shim ONLY while Ui.draw
  -- paints one battle frame, and restore the exact predecessor afterwards.
  -- IMPORTANT: non-Mega calls are forwarded with their ORIGINAL vararg count
  -- and argument types (including quad drawing), not a padded 9-arg list.
  function self.withBattleDraw(drawFn, ...)
    if type(drawFn) ~= "function" then return nil end
    if inBattleDraw or not G or type(G.draw) ~= "function" then
      return drawFn(...)
    end
    local previous = G.draw
    local function scoped(image, ...)
      local pivot = pivots[image]
      if pivot then
        local x, _y, _rotation, _sx, _sy, ox, oy = ...
        if type(x) == "number" and ox == PIC_BOX / 2 and oy == PIC_BOX / 2 then
          local n = select("#", ...)
          local args = { ... }
          args[6], args[7] = pivot[1], pivot[2]
          return previous(image, unpackArgs(args, 1, n))
        end
      end
      -- No mutation, no extra nil arguments, no transformation.
      return previous(image, ...)
    end
    local ok = pcall(function() G.draw = scoped end)
    if not ok then return drawFn(...) end
    inBattleDraw = true
    local function packed(...) return { n = select("#", ...), ... } end
    local result = packed(pcall(drawFn, ...))
    if G.draw == scoped then G.draw = previous end
    inBattleDraw = false
    if not result[1] then error(result[2], 0) end
    return unpackArgs(result, 2, result.n)
  end

  local function installWidePivot()
    -- This is a capability check, not a persistent global hook.
    return G and type(G.draw) == "function" and type(G.newCanvas) == "function"
  end

  local function hdBattle()
    if not mod or type(mod.find) ~= "function" then return nil end
    local ok, found = pcall(mod.find, mod, "gen3-hd-sprites")
    local hd = ok and found and found.exports or nil
    if type(hd) ~= "table" or type(hd.tag) ~= "function" or
        type(hd.enabled) ~= "function" then return nil end
    local okEnabled, enabled = pcall(hd.enabled, "battle")
    return (okEnabled and enabled) and hd or nil
  end

  -- A battle pic can exceed the 64px cartridge cell. Keep the source image
  -- at its intended scale and shift the native pivot to retain feet alignment.
  local function battleLayout(source, spec)
    local fs = source.w
    local s = tonumber(spec.scale) or 1
    s = math.max(0.2, math.min(2, s))
    local foot = tonumber(spec.feet) or fs
    local baseline = tonumber(spec.baseline) or 57
    local ox = (PIC_BOX - fs * s) / 2 + (tonumber(spec.dx) or 0)
    local oy = baseline - foot * s + (tonumber(spec.dy) or 0)
    local border = 96
    local xmin = math.max(-border, math.min(0, math.floor(ox)))
    local xmax = math.min(PIC_BOX + border, math.max(PIC_BOX, math.ceil(ox + fs * s)))
    local ymin = math.max(-border, math.min(0, math.floor(oy)))
    local ymax = math.min(PIC_BOX + border, math.max(PIC_BOX, math.ceil(oy + fs * s)))
    return s, ox, oy, xmin, xmax, ymin, ymax
  end

  local function warnOnce(key, message)
    if logged[key] then return end
    logged[key] = true
    if mod.log and type(mod.log.warn) == "function" then mod.log:warn("%s", message) end
  end

  local function touch(order, key)
    for i = 1, #order do
      if order[i] == key then table.remove(order, i); break end
    end
    order[#order + 1] = key
  end

  local function cache(cacheData, order, key, obj, max)
    cacheData[key] = obj
    touch(order, key)
    while #order > max do
      cacheData[table.remove(order, 1)] = nil
    end
  end

  local function imageFor(filename)
    if not (G and type(G.newImage) == "function") then return nil end
    local hit = pageCache[filename]
    if hit then touch(pageOrder, filename); return hit end
    local path = mod.path .. "/assets/runtime/atlas/" .. filename
    local ok, img = pcall(G.newImage, path)
    if not ok or not img then
      warnOnce(filename, "Mega atlas page unavailable: " .. filename .. " (" .. tostring(img) .. ")")
      return nil
    end
    if img.setFilter then img:setFilter("nearest", "nearest") end
    cache(pageCache, pageOrder, filename, img, 6)
    return img
  end

  local function indexFrame(slug, kind, frame)
    local cell = index.forms[slug] and index.forms[slug].variants
      and index.forms[slug].variants[kind]
    if not cell then return nil end
    local f = frame
    if f == nil then
      local t = type(timer) == "function" and timer() or 0
      f = math.floor((tonumber(t) or 0) * (tonumber(cell.fps) or 8))
    end
    return Atlas.locate(index, slug, kind, f)
  end

  function self.hasSprite(slug, kind)
    return Atlas.locate(index, slug, kind or "front", 0) ~= nil
  end

  function self.formInfo(slug)
    local form = index.forms[slug]
    if not form then return nil end
    -- Deliberately small copy; consumers cannot mutate our atlas coordinates.
    return { slug = slug, species = form.species, display_name = form.display_name,
             pbs_key = form.pbs_key, mega_stone = form.mega_stone,
             source_form = form.source_form }
  end

  function self.locate(slug, kind, frame)
    return indexFrame(slug, kind, frame)
  end

  -- Supply the full-resolution frame for a later HD-sprite integration. Its
  -- texture may outlive the six-page cache if held by another module.
  function self.frame(slug, kind, frame)
    local cell = indexFrame(slug, kind, frame)
    if not cell or not (G and type(G.newQuad) == "function") then return nil end
    local img = imageFor(cell.file)
    if not img then return nil end
    local w, h = img:getDimensions()
    if cell.x + cell.fw > w or cell.y + cell.fh > h then
      warnOnce(cell.file .. ":bounds", "Mega sprite cell outside atlas: " .. cell.file)
      return nil
    end
    local ok, quad = pcall(G.newQuad, cell.x, cell.y, cell.fw, cell.fh, w, h)
    if not ok then return nil end
    return { image = img, quad = quad, w = cell.fs, h = cell.fs,
             cropX = cell.cx, cropY = cell.cy,
             frame = cell.frame, frames = cell.frames, fps = cell.fps }
  end

  -- The public picture() remains a standard fitted 64x64 icon/picture entry.
  -- Battle callers opt in to G9-compatible large sprite sizing. We deliberately
  -- do not touch the global Pokemon.frontPic/backPic wrappers.
  function self.picture(slug, side, shiny, frame, battle)
    if side ~= "front" and side ~= "back" and side ~= "icon" then return nil end
    local kind = side .. (shiny and "_shiny" or "")
    local location = indexFrame(slug, kind, frame)
    if not location then return nil end
    local spec = battle and presentation and presentation[slug]
      and presentation[slug][side] or nil
    local hd = spec and hdBattle() or nil
    local wide = spec and not hd and installWidePivot() or false
    local renderMode = hd and ":hd" or wide and ":wide" or ":fitted"
    local key = slug .. "/" .. kind .. "/" .. location.frame .. renderMode
    local cached = frameCache[key]
    if cached then touch(frameOrder, key); return cached end
    if not (G and type(G.newCanvas) == "function" and type(G.draw) == "function"
        and type(G.setCanvas) == "function" and type(G.push) == "function"
        and type(G.pop) == "function") then return nil end
    local source = self.frame(slug, kind, location.frame)
    if not source then return nil end

    local logicalW, logicalH, ox, oy, xmin, ymin, s = PIC_BOX, PIC_BOX
    if spec then
      local bx, by, xmax, ymax
      s, bx, by, xmin, xmax, ymin, ymax = battleLayout(source, spec)
      if wide then
        logicalW, logicalH = xmax - xmin, ymax - ymin
        ox, oy = bx - xmin, by - ymin
      end
    end
    if not wide then
      -- HD paints the original full-resolution frame above this stand-in;
      -- without HD, fit-to-box remains the safe fallback if global draw
      -- wrapping is restricted by the host.
      local fit = math.min(1, PIC_BOX / source.w, PIC_BOX / source.h)
      s = fit
      ox, oy = (PIC_BOX - source.w * fit) / 2, PIC_BOX - source.h * fit
    end
    local dpi = wide and 2 or 4
    local ok, canvas = pcall(G.newCanvas, logicalW, logicalH, { dpiscale = dpi })
    if not ok or not canvas then
      warnOnce("canvas", "Mega art canvas is unavailable: " .. tostring(canvas))
      return nil
    end
    if canvas.setFilter then canvas:setFilter("nearest", "nearest") end
    G.push("all")
    local drawn, err = pcall(function()
      if G.origin then G.origin() end
      if G.setScissor then G.setScissor() end
      if G.setShader then G.setShader() end
      if G.setBlendMode then G.setBlendMode("alpha") end
      if G.setColor then G.setColor(1, 1, 1, 1) end
      G.setCanvas(canvas)
      if G.clear then G.clear(0, 0, 0, 0) end
      -- This offset exactly restores the frame's position in its original
      -- square source canvas; do not ground or centre individual poses.
      G.draw(source.image, source.quad,
        ox + (source.cropX or 0) * s, oy + (source.cropY or 0) * s,
        0, s, s)
    end)
    G.pop()
    if not drawn then
      warnOnce("draw", "Could not draw Mega sprite: " .. tostring(err))
      return nil
    end
    if wide then
      pivots[canvas] = { PIC_BOX / 2 - xmin, PIC_BOX / 2 - ymin }
    elseif hd then
      local exactScale = tonumber(spec.scale) or 1
      local sourceFeet = tonumber(spec.feet) or source.h
      local sourceBaseline = tonumber(spec.baseline) or 57
      local okTag, errTag = pcall(hd.tag, canvas, {
        texture = source.image,
        quad = source.quad,
        lowPivot = { PIC_BOX / 2 + (tonumber(spec.dx) or 0),
          sourceBaseline + (tonumber(spec.dy) or 0) },
        -- HD drawing uses the cropped quad's coordinates. Translate the
        -- source-space anchor by the common crop, preserving hover height.
        pivot = { source.w / 2 - (source.cropX or 0),
          sourceFeet - (source.cropY or 0) },
        scale = exactScale,
        side = side == "back" and "player" or "enemy",
        top = 0,
        filter = "nearest",
      })
      if not okTag then warnOnce("hd:" .. slug, "Mega HD tag failed: " .. tostring(errTag)) end
    end
    local entry = { image = canvas, w = PIC_BOX, h = PIC_BOX }
    cache(frameCache, frameOrder, key, entry, 48)
    return entry
  end

  function self.stats()
    return { forms = (function() local n = 0; for _ in pairs(index.forms) do n = n + 1 end; return n end)(),
             cachedPages = #pageOrder, cachedFrames = #frameOrder }
  end
  return self
end

return Atlas
